-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 17 recettes, 4 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';
    if jsonb_typeof(ph) is distinct from 'object'
       or nullif(ph->>'url', '') is null or nullif(ph->>'page', '') is null
       or nullif(ph->>'license', '') is null then
      raise exception 'Photo vérifiée obligatoire pour %', r->>'slug';
    end if;
    -- Un nouveau slug ne doit pas recréer un plat déjà importé sous un autre nom.
    if exists (
      select 1 from public.recipes existing
      where existing.id <> rid and existing.country_code = r->>'country'
        and lower(regexp_replace(regexp_replace(coalesce(existing.original_title, existing.title), '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
          = lower(regexp_replace(regexp_replace(r->>'original', '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
    ) then
      raise exception 'Doublon de plat détecté pour %', r->>'slug';
    end if;

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, coalesce(r->>'reference', ph->>'page'),
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"coq-au-vin","country":"FR","original":"Coq au vin","title":"Coq au vin de Bourgogne (volaille braisée au vin rouge)","en":"Coq au vin (chicken braised in Burgundy red wine)","es":"Coq au vin (gallo guisado al vino tinto)","desc":"Coq ou poulet fermier mariné puis braisé au vin rouge de Bourgogne avec lardons, champignons et petits oignons.","cat":"Ragoût","diff":"medium","prep":40,"cook":150,"serv":6,"place":"fr-bourgogne-franche-comte","ing":[["Coq ou poulet fermier",2.5,"kg","en morceaux"],["Vin rouge de Bourgogne",750,"ml",null],["Lardons",200,"g",null],["Champignons de Paris",300,"g",null],["Petits oignons grelots",20,null,null],["Carotte",1,null,"en rondelles"],["Ail",3,"gousses",null],["Bouquet garni",1,null,null],["Farine",2,"c. à soupe",null],["Cognac",50,"ml",null],["Beurre",40,"g",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Mariner la volaille une nuit dans le vin avec carotte, ail et bouquet garni.","Égoutter et dorer les morceaux au beurre; flamber au cognac.","Saupoudrer de farine, mouiller avec la marinade et cuire 2 heures à feu doux.","Faire revenir lardons, oignons grelots et champignons à part.","Les ajouter à la cocotte 20 minutes avant la fin.","Rectifier l’assaisonnement et servir avec des pommes vapeur ou des pâtes fraîches."],"photo":{"file":"File:Coq au vin (Bourgogne) 01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/3/37/Coq_au_vin_%28Bourgogne%29_01.jpg","page":"https://commons.wikimedia.org/wiki/File:Coq_au_vin_(Bourgogne)_01.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"hachis-parmentier","country":"FR","original":"Hachis parmentier","title":"Hachis parmentier (bœuf haché sous purée gratinée)","en":"Hachis parmentier (French beef and mashed potato bake)","es":"Hachis parmentier (pastel de carne picada y puré gratinado)","desc":"Plat familial français nommé en l’honneur d’Antoine Parmentier : viande de bœuf hachée revenue aux oignons, recouverte d’une purée de pommes de terre au beurre puis gratinée au four.","cat":"Plat principal","diff":"easy","prep":30,"cook":45,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Hachis_Parmentier","ing":[["Pommes de terre farineuses",1.2,"kg","pelées"],["Bœuf haché",700,"g",null],["Oignons",2,null,"hachés"],["Ail",2,"gousses","hachées"],["Concentré de tomate",1,"c. à soupe",null],["Bouillon de bœuf",150,"ml",null],["Beurre",80,"g",null],["Lait chaud",250,"ml",null],["Muscade",1,"pincée",null],["Gruyère râpé",80,"g",null],["Persil haché",2,"c. à soupe",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Cuire les pommes de terre 20 minutes dans l’eau salée, les égoutter et les écraser avec 60 g de beurre, le lait chaud, la muscade, sel et poivre.","Faire revenir les oignons dans le reste du beurre, ajouter l’ail puis le bœuf haché et le faire dorer en l’émiettant.","Ajouter le concentré de tomate et le bouillon, laisser réduire 10 minutes, puis incorporer le persil et rectifier l’assaisonnement.","Préchauffer le four à 200 °C. Étaler la viande dans un plat à gratin et la couvrir de purée lissée à la fourchette.","Parsemer de gruyère et gratiner 20 minutes jusqu’à ce que le dessus soit bien doré."],"photo":{"file":"File:Hachis parmentier 01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/5b/Hachis_parmentier_01.jpg","page":"https://commons.wikimedia.org/wiki/File:Hachis_parmentier_01.jpg","author":"Bycro","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"daube-provencale","country":"FR","place":"fr-provence","original":"Daube provençale","title":"Daube provençale (bœuf mariné au vin rouge, olives et orange)","en":"Provençal daube (beef braised in red wine with olives and orange)","es":"Daube provenzal (ternera estofada al vino tinto con aceitunas y naranja)","desc":"Ragoût de bœuf de Provence mariné une nuit dans le vin rouge avec aromates et zeste d’orange, puis mijoté longuement en daubière avec lard, carottes et olives noires.","cat":"Plat principal","diff":"medium","prep":40,"cook":210,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Daube_provençale","ing":[["Bœuf à braiser (paleron, joue)",1.5,"kg","en gros cubes"],["Vin rouge corsé",750,"ml",null],["Lard ou poitrine salée",150,"g","en lardons"],["Oignons",2,null,"émincés"],["Carottes",4,null,"en rondelles"],["Ail",4,"gousses",null],["Zeste d’orange",1,null,"en larges bandes"],["Bouquet garni (thym, laurier, romarin)",1,null,null],["Clous de girofle",2,null,null],["Olives noires",100,"g",null],["Huile d’olive",3,"c. à soupe",null],["Sel et poivre",1,"c. à thé",null]],"steps":["La veille, faire mariner le bœuf avec le vin, les oignons, les carottes, l’ail, le zeste d’orange, le bouquet garni et les clous de girofle.","Égoutter la viande en gardant la marinade, l’éponger et la faire dorer dans l’huile d’olive avec les lardons.","Ajouter les légumes et la marinade, porter à frémissement, saler et poivrer.","Couvrir et laisser mijoter 3 heures à feu très doux ou au four à 150 °C.","Ajouter les olives 30 minutes avant la fin. Servir avec des pâtes fraîches ou des pommes de terre vapeur."],"photo":{"file":"File:Daube provençale 03.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/8/8b/Daube_proven%C3%A7ale_03.jpg","page":"https://commons.wikimedia.org/wiki/File:Daube_proven%C3%A7ale_03.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"confit-de-canard","country":"FR","place":{"slug":"fr-gascogne","name":"Gascogne","type":"region","lat":43.7,"lng":0.3,"summary":"Pays du Sud-Ouest réputé pour le canard gras : confit, magret et foie gras, garbure et armagnac."},"original":"Confit de canard","title":"Confit de canard (cuisses cuites et conservées dans leur graisse)","en":"Duck confit","es":"Confit de pato","desc":"Spécialité du Sud-Ouest : cuisses de canard salées une nuit puis cuites lentement dans leur graisse jusqu’à devenir fondantes, et dorées à la poêle pour une peau croustillante.","cat":"Plat principal","diff":"medium","prep":20,"cook":180,"serv":4,"reference":"https://fr.wikipedia.org/wiki/Confit_de_canard","ing":[["Cuisses de canard",4,null,null],["Gros sel",60,"g",null],["Graisse de canard",1,"kg",null],["Ail",4,"gousses","écrasées"],["Thym",4,"branches",null],["Laurier",2,"feuilles",null],["Poivre noir concassé",1,"c. à thé",null],["Pommes de terre",800,"g","pour les pommes sarladaises, facultatif"]],"steps":["Frotter les cuisses de gros sel, de poivre et de thym émietté, et les laisser au réfrigérateur 12 heures.","Rincer et éponger soigneusement les cuisses.","Faire fondre la graisse de canard dans une cocotte, y plonger les cuisses avec l’ail et le laurier : elles doivent être couvertes.","Cuire à frémissement très doux (environ 90 °C) pendant 2 h 30 à 3 heures, jusqu’à ce que la viande se détache de l’os.","Pour servir, dorer les cuisses côté peau dans une poêle chaude ou sous le gril 10 minutes, et faire sauter les pommes de terre dans un peu de graisse."],"photo":{"file":"File:Confit de canard.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/64/Confit_de_canard.jpg","page":"https://commons.wikimedia.org/wiki/File:Confit_de_canard.jpg","author":"Nikchick","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0"}},{"slug":"moules-marinieres","country":"FR","original":"Moules marinières","title":"Moules marinières (au vin blanc, échalotes et persil)","en":"Moules marinières (mussels in white wine)","es":"Mejillones a la marinera (al vino blanco)","desc":"Le grand classique des côtes françaises : moules ouvertes à feu vif dans le vin blanc avec échalotes, beurre et persil, servies dans leur jus avec du pain ou des frites.","cat":"Fruits de mer","diff":"easy","prep":20,"cook":10,"serv":4,"reference":"https://fr.wikipedia.org/wiki/Moules_marinières","ing":[["Moules de bouchot",2,"kg","grattées et ébarbées"],["Échalotes",3,null,"ciselées"],["Beurre",40,"g",null],["Vin blanc sec",250,"ml",null],["Persil plat",1,"bouquet","haché"],["Thym",2,"branches",null],["Laurier",1,"feuille",null],["Crème fraîche",3,"c. à soupe","facultatif"],["Poivre",0.5,"c. à thé",null]],"steps":["Rincer les moules et jeter celles qui restent ouvertes après un petit choc.","Faire fondre le beurre dans une grande marmite et y faire suer les échalotes 2 minutes.","Ajouter le vin blanc, le thym, le laurier et le poivre, porter à ébullition.","Verser les moules, couvrir et cuire 5 à 7 minutes à feu vif en secouant la marmite, jusqu’à ce qu’elles soient toutes ouvertes.","Ajouter le persil (et la crème), mélanger et servir aussitôt avec le jus de cuisson."],"photo":{"file":"File:Moules marinières.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/68/Moules_marini%C3%A8res.jpg","page":"https://commons.wikimedia.org/wiki/File:Moules_marini%C3%A8res.jpg","author":"Thomon","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"sole-meuniere","country":"FR","place":"fr-paris","original":"Sole meunière","title":"Sole meunière (farinée, poêlée au beurre noisette et citron)","en":"Sole meunière","es":"Lenguado a la meunière","desc":"Classique des brasseries parisiennes : sole entière légèrement farinée, dorée au beurre puis arrosée de beurre noisette, de jus de citron et de persil.","cat":"Poisson","diff":"medium","prep":15,"cook":15,"serv":2,"reference":"https://fr.wikipedia.org/wiki/Sole_meunière","ing":[["Soles entières",2,null,"de 400 g, vidées et pelées"],["Farine",50,"g",null],["Beurre",100,"g",null],["Huile neutre",1,"c. à soupe",null],["Citron",1,null,"jus et quartiers"],["Persil plat",2,"c. à soupe","haché"],["Sel et poivre",1,"c. à thé",null],["Pommes de terre vapeur",400,"g","pour servir"]],"steps":["Saler et poivrer les soles, puis les fariner légèrement en secouant l’excédent.","Chauffer l’huile et 30 g de beurre dans une grande poêle et cuire les soles 4 à 5 minutes par côté, en les arrosant.","Réserver les soles au chaud sur les assiettes.","Essuyer la poêle, y faire fondre le reste du beurre jusqu’à ce qu’il devienne noisette, ajouter le jus de citron et le persil.","Napper aussitôt les soles de ce beurre et servir avec les pommes de terre et les quartiers de citron."],"photo":{"file":"File:Brasserie Lipp 007.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/6e/Brasserie_Lipp_007.jpg","page":"https://commons.wikimedia.org/wiki/File:Brasserie_Lipp_007.jpg","author":"Arnaud 25","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en"}},{"slug":"paris-brest","country":"FR","place":"fr-ile-de-france","original":"Paris-Brest","title":"Paris-Brest (couronne de pâte à choux, crème mousseline praliné)","en":"Paris-Brest (choux pastry ring with praline cream)","es":"Paris-Brest (corona de masa choux con crema de praliné)","desc":"Pâtisserie créée en 1910 par Louis Durand à Maisons-Laffitte pour la course cycliste Paris–Brest–Paris : une couronne de pâte à choux aux amandes effilées garnie de crème mousseline au praliné.","cat":"Dessert","diff":"hard","prep":60,"cook":40,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Paris-Brest","ing":[["Eau (pâte à choux)",125,"ml",null],["Lait (pâte à choux)",125,"ml",null],["Beurre (pâte à choux)",100,"g",null],["Farine",150,"g",null],["Œufs (pâte à choux)",4,null,null],["Amandes effilées",40,"g",null],["Lait (crème)",500,"ml",null],["Jaunes d’œufs",4,null,null],["Sucre",100,"g",null],["Fécule de maïs",40,"g",null],["Praliné noisette",150,"g",null],["Beurre mou (crème)",150,"g",null],["Sucre glace",1,"c. à soupe","pour le décor"]],"steps":["Pâte à choux : porter à ébullition l’eau, le lait, le beurre et une pincée de sel, ajouter la farine d’un coup et dessécher 1 minute, puis incorporer les œufs un à un.","Pocher une couronne de 22 cm sur une plaque, parsemer d’amandes effilées et cuire 35 à 40 minutes à 180 °C sans ouvrir le four.","Crème : cuire le lait, les jaunes, le sucre et la fécule en crème pâtissière épaisse; laisser refroidir sous film.","Fouetter le beurre mou avec le praliné, puis incorporer la crème pâtissière refroidie pour obtenir une mousseline.","Couper la couronne en deux dans l’épaisseur, garnir généreusement de crème à la douille cannelée, refermer et saupoudrer de sucre glace."],"photo":{"file":"File:Paris-Brest IMG 0875.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/d/de/Paris-Brest_IMG_0875.JPG","page":"https://commons.wikimedia.org/wiki/File:Paris-Brest_IMG_0875.JPG","author":"Deror_avi","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"escargots-de-bourgogne","country":"FR","place":"fr-bourgogne-franche-comte","original":"Escargots de Bourgogne","title":"Escargots à la bourguignonne (beurre persillé à l’ail)","en":"Burgundy snails with garlic and parsley butter","es":"Caracoles a la borgoñona (mantequilla de ajo y perejil)","desc":"Entrée emblématique de la Bourgogne : escargots replacés dans leur coquille, scellés d’un beurre d’escargot à l’ail, à l’échalote et au persil, puis passés au four jusqu’à ce que le beurre grésille.","cat":"Entrée","diff":"medium","prep":30,"cook":10,"serv":4,"reference":"https://fr.wikipedia.org/wiki/Escargots_de_Bourgogne","ing":[["Escargots de Bourgogne préparés",48,null,"avec leurs coquilles"],["Beurre mou",250,"g",null],["Ail",4,"gousses","très finement hachées"],["Échalote",1,null,"ciselée"],["Persil plat",1,"bouquet","finement haché"],["Sel",1,"c. à thé",null],["Poivre",0.5,"c. à thé",null],["Pain de campagne",1,null,"pour saucer"]],"steps":["Préchauffer le four à 220 °C.","Écraser le beurre mou avec l’ail, l’échalote, le persil, le sel et le poivre jusqu’à obtenir une pommade homogène.","Glisser une noisette de beurre au fond de chaque coquille, y enfoncer un escargot et fermer avec une bonne couche de beurre.","Disposer les coquilles ouverture vers le haut dans des plats à escargots.","Enfourner 8 à 10 minutes jusqu’à ce que le beurre grésille et servir aussitôt avec du pain."],"photo":{"file":"File:Escargots à la bourguignonne.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/8/84/Escargots_%C3%A0_la_bourguignonne.jpg","page":"https://commons.wikimedia.org/wiki/File:Escargots_%C3%A0_la_bourguignonne.jpg","author":"Thomon","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"tripes-a-la-mode-de-caen","country":"FR","place":{"slug":"fr-caen","name":"Caen","type":"city","lat":49.1829,"lng":-0.3707,"summary":"Ville du Calvados, en Normandie, berceau des tripes à la mode de Caen."},"original":"Tripes à la mode de Caen","title":"Tripes à la mode de Caen (braisées au cidre et au calvados)","en":"Tripes à la mode de Caen (tripe braised in cider and calvados)","es":"Callos a la moda de Caen (estofados en sidra y calvados)","desc":"Spécialité normande : tripes de bœuf et pied de veau mijotés très longuement au four avec carottes, oignons, cidre et calvados, dans une tripière lutée.","cat":"Plat principal","diff":"hard","prep":40,"cook":600,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Tripes_à_la_mode_de_Caen","ing":[["Tripes de bœuf (panse, feuillet, caillette)",2,"kg","blanchies"],["Pied de veau",1,null,"fendu"],["Carottes",4,null,"en rondelles"],["Oignons",3,null,"piqués de clous de girofle"],["Poireaux",2,null,"le blanc"],["Bouquet garni",1,null,null],["Cidre brut",750,"ml",null],["Calvados",100,"ml",null],["Graisse de bœuf",150,"g",null],["Sel et poivre",2,"c. à thé",null],["Farine et eau (pâte à luter)",200,"g",null]],"steps":["Couper les tripes en carrés de 5 cm et les blanchir 10 minutes à l’eau bouillante, puis rafraîchir.","Tapisser une tripière (ou cocotte en fonte) de graisse de bœuf, y mettre le pied de veau, les légumes et le bouquet garni, puis les tripes; saler et poivrer.","Mouiller avec le cidre et le calvados jusqu’à hauteur.","Fermer le couvercle et le souder avec une pâte de farine et d’eau.","Cuire 10 heures au four à 120 °C. Retirer les os et le bouquet, dégraisser et servir très chaud avec des pommes de terre vapeur."],"photo":{"file":"File:Tripes à la mode de Caen.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/57/Tripes_%C3%A0_la_mode_de_Caen.jpg","page":"https://commons.wikimedia.org/wiki/File:Tripes_%C3%A0_la_mode_de_Caen.jpg","author":"Manuel.flury","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"nougat-de-montelimar","country":"FR","place":{"slug":"fr-montelimar","name":"Montélimar","type":"city","lat":44.5581,"lng":4.7509,"summary":"Ville de la Drôme, capitale du nougat blanc au miel de lavande et aux amandes."},"original":"Nougat de Montélimar","title":"Nougat de Montélimar (blanc au miel, amandes et pistaches)","en":"Montélimar nougat (white honey nougat with almonds and pistachios)","es":"Turrón de Montélimar (blanco de miel, almendras y pistachos)","desc":"Confiserie de la Drôme : blancs d’œufs montés et cuits avec un sirop de sucre et de miel de lavande, enrichis d’amandes et de pistaches, puis coulés entre deux feuilles de papier azyme.","cat":"Dessert","diff":"hard","prep":40,"cook":30,"serv":20,"reference":"https://fr.wikipedia.org/wiki/Nougat_de_Montélimar","ing":[["Miel de lavande",250,"g",null],["Sucre",300,"g",null],["Glucose",50,"g",null],["Eau",80,"ml",null],["Blancs d’œufs",2,null,null],["Amandes émondées",300,"g","torréfiées"],["Pistaches",60,"g",null],["Vanille",1,"gousse","grattée"],["Papier azyme",2,"feuilles",null]],"steps":["Chauffer le miel à 120 °C d’un côté, et le sucre, le glucose et l’eau à 145 °C de l’autre.","Monter les blancs en neige ferme, verser le miel chaud en filet en fouettant, puis le sirop de sucre.","Continuer de fouetter 10 minutes au bain-marie jusqu’à ce que la pâte devienne épaisse et collante; ajouter la vanille.","Incorporer rapidement les amandes chaudes et les pistaches.","Étaler entre deux feuilles de papier azyme dans un cadre, presser, laisser durcir une nuit puis couper en barres au couteau chaud."],"photo":{"file":"File:Nougat de Montélimar - 20090704.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/7/78/Nougat_de_Mont%C3%A9limar_-_20090704.jpg","page":"https://commons.wikimedia.org/wiki/File:Nougat_de_Mont%C3%A9limar_-_20090704.jpg","author":"Sémhur","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"rillettes-du-mans","country":"FR","place":{"slug":"fr-le-mans","name":"Le Mans","type":"city","lat":48.0061,"lng":0.1996,"summary":"Préfecture de la Sarthe, capitale des rillettes de porc."},"original":"Rillettes du Mans","title":"Rillettes du Mans (porc confit et effiloché dans sa graisse)","en":"Le Mans pork rillettes","es":"Rillettes de Le Mans (cerdo confitado y deshebrado)","desc":"Spécialité de la Sarthe : échine et poitrine de porc cuites très lentement dans leur graisse avec un peu de vin blanc, puis effilochées à la fourchette et mises en pots sous une couche de saindoux.","cat":"Entrée","diff":"easy","prep":20,"cook":300,"serv":10,"reference":"https://fr.wikipedia.org/wiki/Rillettes","ing":[["Échine de porc",1,"kg","en gros cubes"],["Poitrine de porc fraîche",500,"g","en cubes"],["Saindoux",300,"g",null],["Vin blanc sec",150,"ml",null],["Bouquet garni",1,null,null],["Gros sel",20,"g",null],["Poivre",1,"c. à thé",null],["Quatre-épices",0.5,"c. à thé",null]],"steps":["Faire fondre le saindoux dans une cocotte en fonte et y faire revenir la viande sans la colorer.","Ajouter le vin blanc, le bouquet garni, le sel, le poivre et les épices.","Couvrir et cuire 5 heures à feu très doux en remuant de temps en temps, jusqu’à ce que la viande se défasse.","Retirer le bouquet, effilocher la viande à la fourchette en la mélangeant à sa graisse.","Remplir des pots, laisser refroidir puis réfrigérer; servir à température ambiante sur du pain grillé."],"photo":{"file":"File:Rillettes du Mans.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/2/24/Rillettes_du_Mans.jpg","page":"https://commons.wikimedia.org/wiki/File:Rillettes_du_Mans.jpg","author":"Nikchick","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0"}},{"slug":"poulet-basquaise","country":"FR","place":"fr-pays-basque","original":"Poulet basquaise","title":"Poulet basquaise (mijoté aux poivrons, tomates et piment d’Espelette)","en":"Basque-style chicken with peppers and tomatoes","es":"Pollo a la vasca (con pimientos, tomate y pimiento de Espelette)","desc":"Poulet doré puis mijoté dans une piperade de poivrons verts et rouges, de tomates, d’oignons et d’ail, relevée de piment d’Espelette et parfois de jambon de Bayonne.","cat":"Plat principal","diff":"easy","prep":25,"cook":60,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Poulet_basquaise","ing":[["Poulet fermier",1.6,"kg","en morceaux"],["Poivrons verts",2,null,"en lanières"],["Poivrons rouges",2,null,"en lanières"],["Tomates",6,null,"pelées et concassées"],["Oignons",2,null,"émincés"],["Ail",3,"gousses",null],["Jambon de Bayonne",2,"tranches","en lanières, facultatif"],["Vin blanc sec",150,"ml",null],["Huile d’olive",4,"c. à soupe",null],["Piment d’Espelette",1,"c. à thé",null],["Bouquet garni",1,null,null],["Sel",1,"c. à thé",null]],"steps":["Dorer les morceaux de poulet dans la moitié de l’huile d’olive, les saler et les réserver.","Dans la même cocotte, faire fondre les oignons et les poivrons 10 minutes avec le reste de l’huile.","Ajouter l’ail, le jambon, les tomates, le piment d’Espelette et le bouquet garni.","Remettre le poulet, mouiller avec le vin blanc, couvrir et laisser mijoter 45 minutes.","Rectifier l’assaisonnement et servir avec du riz blanc."],"photo":{"file":"File:Poulet basquaise 01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/98/Poulet_basquaise_01.jpg","page":"https://commons.wikimedia.org/wiki/File:Poulet_basquaise_01.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"axoa-basque","country":"FR","place":"fr-pays-basque","original":"Axoa","title":"Axoa basque (veau haché au couteau, piments doux et Espelette)","en":"Basque axoa (minced veal with peppers and Espelette pepper)","es":"Axoa vasco (ternera picada a cuchillo con pimientos y Espelette)","desc":"Plat traditionnel d’Espelette et de Soule : épaule de veau hachée au couteau, mijotée avec oignons, piments doux (ezpeleta) et piment d’Espelette, servie avec des pommes de terre.","cat":"Plat principal","diff":"easy","prep":25,"cook":45,"serv":4,"reference":"https://fr.wikipedia.org/wiki/Axoa","ing":[["Épaule de veau",800,"g","hachée au couteau en petits dés"],["Oignons",2,null,"émincés"],["Piments doux verts (type Anglet)",4,null,"en dés"],["Poivron rouge",1,null,"en dés"],["Ail",2,"gousses",null],["Piment d’Espelette",1,"c. à thé",null],["Bouillon de veau",200,"ml",null],["Huile d’olive",3,"c. à soupe",null],["Sel",1,"c. à thé",null],["Pommes de terre",800,"g","vapeur, pour servir"]],"steps":["Faire fondre les oignons dans l’huile d’olive, puis ajouter les piments doux, le poivron et l’ail; cuire 10 minutes.","Ajouter le veau et le faire revenir à feu vif en remuant jusqu’à ce qu’il perde sa couleur rosée.","Saupoudrer de piment d’Espelette, saler, mouiller avec le bouillon.","Couvrir et laisser mijoter 30 minutes à feu doux.","Servir chaud avec des pommes de terre vapeur."],"photo":{"file":"File:Axoa (Mauléon-Licharre).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/d/db/Axoa_%28Maul%C3%A9on-Licharre%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Axoa_(Maul%C3%A9on-Licharre).jpg","author":"Tangopaso","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"jambon-persille-bourgogne","country":"FR","place":"fr-bourgogne-franche-comte","original":"Jambon persillé","title":"Jambon persillé de Bourgogne (terrine de jambon en gelée au persil)","en":"Burgundy jambon persillé (ham and parsley terrine)","es":"Jamón perejilado de Borgoña (terrina de jamón en gelatina de perejil)","desc":"Terrine pascale de Bourgogne : jambon cuit au vin blanc avec un jarret et un pied de veau, effiloché puis pris dans une gelée très verte de persil, d’ail et d’échalote.","cat":"Entrée","diff":"medium","prep":45,"cook":180,"serv":10,"reference":"https://fr.wikipedia.org/wiki/Jambon_persillé","ing":[["Jambon cru demi-sel (épaule ou cuisse)",1.5,"kg","dessalé"],["Jarret de veau",1,null,null],["Pied de veau",1,null,"fendu"],["Vin blanc de Bourgogne (aligoté)",750,"ml",null],["Bouquet garni",1,null,null],["Échalotes",3,null,"ciselées"],["Ail",3,"gousses","hachées"],["Persil plat",2,"bouquets","haché"],["Vinaigre de vin",1,"c. à soupe",null],["Poivre",1,"c. à thé",null]],"steps":["Dessaler le jambon une nuit dans l’eau froide, puis le blanchir 10 minutes.","Le cuire 2 h 30 à frémissement avec le jarret, le pied de veau, le vin blanc et le bouquet garni.","Égoutter les viandes, filtrer et réduire le bouillon de moitié, puis y ajouter le vinaigre.","Effilocher le jambon et mélanger avec le persil, l’ail, l’échalote et le poivre.","Remplir une terrine en tassant, couvrir de bouillon tiède et réfrigérer 24 heures avant de servir en tranches."],"photo":{"file":"File:Jambon persillé.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/3/38/Jambon_persill%C3%A9.JPG","page":"https://commons.wikimedia.org/wiki/File:Jambon_persill%C3%A9.JPG","author":"Arnaud 25","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"canistrelli-corses","country":"FR","place":"fr-corse","original":"Canistrelli","title":"Canistrelli corses (biscuits secs à l’huile d’olive et au vin blanc)","en":"Corsican canistrelli (olive oil and white wine biscuits)","es":"Canistrelli corsos (galletas de aceite de oliva y vino blanco)","desc":"Biscuits secs et friables de Corse, sans beurre ni œufs : farine, sucre, huile d’olive et vin blanc, parfumés à l’anis, au citron ou nature, coupés en losanges et roulés dans le sucre.","cat":"Dessert","diff":"easy","prep":20,"cook":25,"serv":30,"reference":"https://fr.wikipedia.org/wiki/Canistrelli","ing":[["Farine",500,"g",null],["Sucre",200,"g","et un peu pour l’enrobage"],["Huile d’olive",150,"ml",null],["Vin blanc sec",150,"ml",null],["Levure chimique",1,"sachet","11 g"],["Graines d’anis",1,"c. à soupe","ou zeste de citron"],["Sel",1,"pincée",null]],"steps":["Préchauffer le four à 180 °C.","Mélanger la farine, le sucre, la levure, le sel et l’anis.","Ajouter l’huile d’olive et le vin blanc et pétrir rapidement en une pâte souple.","Abaisser sur 1,5 cm d’épaisseur, couper en losanges ou en rectangles et les passer dans le sucre.","Cuire 20 à 25 minutes jusqu’à ce qu’ils soient dorés. Laisser refroidir sur grille : ils se conservent des semaines en boîte."],"photo":{"file":"File:Canistrelli nature.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/c/cd/Canistrelli_nature.jpg","page":"https://commons.wikimedia.org/wiki/File:Canistrelli_nature.jpg","author":"Chatsam","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"croque-madame","country":"FR","place":"fr-paris","original":"Croque-madame","title":"Croque-madame (croque-monsieur coiffé d’un œuf au plat)","en":"Croque-madame","es":"Croque-madame (sándwich gratinado con huevo frito)","desc":"Variante parisienne du croque-monsieur : pain de mie, jambon, béchamel et emmental gratinés au four, couronnés d’un œuf au plat au jaune coulant.","cat":"Street food","diff":"easy","prep":15,"cook":15,"serv":2,"reference":"https://fr.wikipedia.org/wiki/Croque-madame","ing":[["Pain de mie",4,"tranches",null],["Jambon blanc",2,"tranches",null],["Emmental ou gruyère râpé",100,"g",null],["Beurre",30,"g",null],["Farine",15,"g","pour la béchamel"],["Lait",150,"ml","pour la béchamel"],["Muscade",1,"pincée",null],["Œufs",2,null,null],["Sel et poivre",1,"pincée",null]],"steps":["Béchamel : faire fondre 15 g de beurre, ajouter la farine, puis le lait en fouettant jusqu’à épaississement; assaisonner de sel, poivre et muscade.","Beurrer légèrement l’extérieur des tranches de pain. Garnir deux tranches de béchamel, de jambon et d’un peu de fromage, puis refermer.","Napper le dessus de béchamel et parsemer de fromage.","Gratiner 10 à 12 minutes au four à 220 °C.","Pendant ce temps, cuire les œufs au plat et en déposer un sur chaque croque avant de servir."],"photo":{"file":"File:Croque Madame, Paris July 6, 2011 (cropped).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/ab/Croque_Madame%2C_Paris_July_6%2C_2011_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Croque_Madame,_Paris_July_6,_2011_(cropped).jpg","author":"Nicki Dugan Pogue","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0"}},{"slug":"creme-brulee","country":"FR","original":"Crème brûlée","title":"Crème brûlée (crème vanillée à la croûte de sucre caramélisé)","en":"Crème brûlée","es":"Crème brûlée (crema de vainilla con costra de azúcar caramelizado)","desc":"Crème à la vanille cuite doucement au bain-marie, refroidie puis saupoudrée de cassonade caramélisée au chalumeau pour former une fine croûte craquante.","cat":"Dessert","diff":"medium","prep":20,"cook":45,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Crème_brûlée","ing":[["Crème liquide entière",500,"ml",null],["Lait entier",100,"ml",null],["Jaunes d’œufs",6,null,null],["Sucre",90,"g",null],["Gousse de vanille",1,null,"fendue et grattée"],["Cassonade",60,"g","pour la croûte"]],"steps":["Préchauffer le four à 100 °C. Chauffer la crème et le lait avec la vanille sans faire bouillir, puis laisser infuser 15 minutes.","Fouetter les jaunes avec le sucre sans faire mousser, puis verser la crème chaude filtrée en remuant.","Répartir dans des ramequins plats et cuire 40 à 45 minutes au bain-marie : la crème doit être prise mais encore tremblante au centre.","Laisser refroidir puis réfrigérer au moins 4 heures.","Au moment de servir, saupoudrer de cassonade et caraméliser au chalumeau jusqu’à obtenir une croûte ambrée."],"photo":{"file":"File:Creme Brulee (retouched).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/b/bf/Creme_Brulee_%28retouched%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Creme_Brulee_(retouched).jpg","author":"Lopside (retouche : Hic et nunc)","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}}]$batch$::jsonb);
